"""Kiro PreToolUse guard: block a tool call whose input carries a credential value.

Generated by Hauntlet's Exorcist. It uses the standard library only. Kiro
passes the hook event as JSON on stdin. The guard reads only that JSON and its
own environment, and it makes no network call, writes no file and starts no
process.

Exit 2 blocks the call (edited locally); exit 0 allows it (Kiro docs, "Hook actions"). On a
block it names the variable,
never its value. Input that is not a JSON object is allowed, because a guard
must not turn its own parse failure into a silent block.

Limit: it only knows credentials that are in its environment. Whether Kiro
passes its environment to hook commands is not documented, so this is
unverified (assumption A4).
"""

import json
import os
import re
import sys
from urllib.parse import quote, quote_plus

#: Environment variables whose names look like credentials.
CREDENTIAL_NAME = re.compile(r"KEY|TOKEN|SECRET|SESSION|PASSWORD|CREDENTIAL", re.IGNORECASE)
MIN_SECRET_LEN = 12


def main() -> int:
    try:
        event = json.loads(sys.stdin.read())
    except ValueError:
        return 0
    if not isinstance(event, dict):
        return 0
    blob = json.dumps(event.get("tool_input"), sort_keys=True, ensure_ascii=False)
    for name, value in sorted(os.environ.items()):
        if not CREDENTIAL_NAME.search(name) or len(value) < MIN_SECRET_LEN:
            continue
        if value in blob or quote(value, safe="") in blob or quote_plus(value) in blob:
            sys.stderr.write(f"blocked: the tool input carries the value of {name}\n")
            return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
